/* Runtime for the statically recompiled game: CPU state, memory bus, cycle clock and PPU.
 * The recompiled routines (generated by tools/recomp.py from the user's own ROM) include this header. */
#ifndef GB_RT_H
#define GB_RT_H
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { uint8_t a, f, b, c, d, e, h, l; uint16_t sp; } Regs;
extern Regs r;
extern int ime;                    /* interrupt master enable */
extern uint64_t cycles;            /* machine cycles (4.19 MHz clock ticks) */

typedef void *(*fn_t)(void);       /* a routine returns the routine to continue with (tail jump) or NULL (ret) */

uint8_t rd(uint16_t a);
void wr(uint16_t a, uint8_t v);
void gb_service(void);             /* no-op (kept for old generated code) */
void gb_host_vblank(void);         /* one frame: render, mix sound, present, then run the game's VBlankHandler */
fn_t gb_dispatch(uint16_t addr);   /* indirect jump: find the routine at an address in the current bank */
void gb_fatal(const char *why, unsigned v);
void gb_dma_routine(void);

#define A r.a
#define F r.f
#define B r.b
#define C r.c
#define D r.d
#define E_ r.e
#define H r.h
#define L r.l
#define BC() ((uint16_t)(r.b << 8 | r.c))
#define DE() ((uint16_t)(r.d << 8 | r.e))
#define HL() ((uint16_t)(r.h << 8 | r.l))
#define SET_BC(v) do { uint16_t t_ = (v); r.b = t_ >> 8; r.c = t_; } while (0)
#define SET_DE(v) do { uint16_t t_ = (v); r.d = t_ >> 8; r.e = t_; } while (0)
#define SET_HL(v) do { uint16_t t_ = (v); r.h = t_ >> 8; r.l = t_; } while (0)
#define CYC(n) ((void)0)           /* no cycle counting: the game is driven one frame at a time */
#define ZF() (r.f & 0x80)
#define CF() (r.f & 0x10)

/* Run a routine to completion, following tail jumps. */
extern int gb_trace;
void gb_trace_fn(fn_t f);
static inline void gb_run(fn_t f) { while (f) { if (gb_trace) gb_trace_fn(f); f = (fn_t)f(); } }
/* `call` reserves the return address slot; `ret` releases it. A callee that discarded its return address (pop hl; ... ret) makes
 * the stack end above where we left it: that ret already returned for us too, so this routine returns as well. */
#define CALL(fn) do { uint16_t sp0_ = r.sp; r.sp -= 2; gb_run((fn_t)(fn)); if (r.sp > sp0_) return 0; } while (0)
/* Called on every backward branch: this is where waiting loops let interrupts and the PPU run. */
extern unsigned gb_spin;
/* A backward branch counts as spinning; a loop that waits for something only the VBlank handler can change gets a frame after 60000 turns. */
#define BACKEDGE() do { if (++gb_spin > 60000) gb_host_vblank(); } while (0)

static inline void push16(uint16_t v) { r.sp -= 2; wr(r.sp + 1, v >> 8); wr(r.sp, v & 255); }
static inline uint16_t pop16(void) { uint16_t v = rd(r.sp) | rd(r.sp + 1) << 8; r.sp += 2; return v; }

static inline void alu_add(uint8_t v, int c) { unsigned x = r.a + v + c; r.f = (((r.a & 15) + (v & 15) + c) > 15 ? 0x20 : 0) | (x > 255 ? 0x10 : 0) | ((x & 255) ? 0 : 0x80); r.a = x; }
static inline uint8_t alu_sub_f(uint8_t v, int c) { int x = r.a - v - c; r.f = 0x40 | (((r.a & 15) - (v & 15) - c) < 0 ? 0x20 : 0) | (x < 0 ? 0x10 : 0) | ((x & 255) ? 0 : 0x80); return (uint8_t)x; }
static inline void alu_sub(uint8_t v, int c) { r.a = alu_sub_f(v, c); }
static inline void alu_cp(uint8_t v) { alu_sub_f(v, 0); }
static inline void alu_and(uint8_t v) { r.a &= v; r.f = 0x20 | (r.a ? 0 : 0x80); }
static inline void alu_xor(uint8_t v) { r.a ^= v; r.f = r.a ? 0 : 0x80; }
static inline void alu_or(uint8_t v) { r.a |= v; r.f = r.a ? 0 : 0x80; }
static inline uint8_t inc8(uint8_t v) { uint8_t x = v + 1; r.f = (r.f & 0x10) | (x ? 0 : 0x80) | ((v & 15) == 15 ? 0x20 : 0); return x; }
static inline uint8_t dec8(uint8_t v) { uint8_t x = v - 1; r.f = (r.f & 0x10) | 0x40 | (x ? 0 : 0x80) | ((v & 15) == 0 ? 0x20 : 0); return x; }
static inline void add_hl(uint16_t v) { uint16_t h = HL(); uint32_t x = h + v; r.f = (r.f & 0x80) | (((h & 0xFFF) + (v & 0xFFF)) > 0xFFF ? 0x20 : 0) | (x > 0xFFFF ? 0x10 : 0); SET_HL(x); }
static inline void op_rlca(void) { int c = r.a >> 7; r.a = (r.a << 1) | c; r.f = c ? 0x10 : 0; }
static inline void op_rrca(void) { int c = r.a & 1; r.a = (r.a >> 1) | (c << 7); r.f = c ? 0x10 : 0; }
static inline void op_rla(void) { int c = r.a >> 7; r.a = (r.a << 1) | (r.f & 0x10 ? 1 : 0); r.f = c ? 0x10 : 0; }
static inline void op_rra(void) { int c = r.a & 1; r.a = (r.a >> 1) | (r.f & 0x10 ? 0x80 : 0); r.f = c ? 0x10 : 0; }
static inline void op_daa(void) {
    int a = r.a, adj = 0, c = r.f & 0x10;
    if (r.f & 0x40) { if (r.f & 0x20) adj |= 6; if (c) adj |= 0x60; a = (a - adj) & 255; }
    else { if ((r.f & 0x20) || (a & 15) > 9) adj |= 6; if (c || a > 0x99) { adj |= 0x60; c = 0x10; } a = (a + adj) & 255; }
    r.a = a; r.f = (r.f & 0x40) | (a ? 0 : 0x80) | c;
}
static inline uint8_t cb_rot(int k, uint8_t v) {
    int c = (r.f & 0x10) ? 1 : 0, nc;
    switch (k) {
    case 0: nc = v >> 7; v = (v << 1) | nc; break;
    case 1: nc = v & 1; v = (v >> 1) | (nc << 7); break;
    case 2: nc = v >> 7; v = (v << 1) | c; break;
    case 3: nc = v & 1; v = (v >> 1) | (c << 7); break;
    case 4: nc = v >> 7; v <<= 1; break;
    case 5: nc = v & 1; v = (v >> 1) | (v & 0x80); break;
    case 6: nc = 0; v = (v << 4) | (v >> 4); break;
    default: nc = v & 1; v >>= 1; break;
    }
    r.f = (v ? 0 : 0x80) | (nc ? 0x10 : 0);
    return v;
}
static inline void cb_bit(int n, uint8_t v) { r.f = (r.f & 0x10) | 0x20 | ((v >> n) & 1 ? 0 : 0x80); }
static inline uint16_t sp_plus(int8_t d) { uint16_t sp = r.sp; r.f = (((sp & 15) + (d & 15)) > 15 ? 0x20 : 0) | (((sp & 255) + (uint8_t)d) > 255 ? 0x10 : 0); return sp + d; }

/* PPU / platform layer */
extern uint8_t gb_joy;             /* pressed buttons, bit layout of emu.py BTN */
extern uint8_t gb_framebuf[160 * 144];   /* shade 0-3 per pixel, rendered at the start of VBlank */
extern void (*gb_frame_hook)(unsigned frame);
extern void (*gb_audio_hook)(const int16_t *stereo, int frames);
void gb_load_rom(const uint8_t *data, size_t size);
void gb_reset_state(void);
extern unsigned gb_frames;
#endif
